"use strict";(globalThis.webpackChunkgrc||=[]).push([[27242],{63887(e){e.exports=JSON.parse('{"citeKey":"rajesh2024tunio","slug":"rajesh-2024-tunio-05a8","title":"TunIO: An AI-powered Framework for Optimizing HPC I/O","authors":["N. Rajesh","K. Bateman","S. Byna","J. L. Bez","A. Kougkas","X.-H. Sun"],"venue":"The 38th IEEE International Parallel & Distributed Processing Symposium (IPDPS 2024)","type":"Conference","entryType":"inproceedings","date":"May, 2024","year":2024,"era":"iit","month":5,"doi":"10.1109/ipdps57955.2024.00050","abstract":"I/O operations are a known performance bottleneck of HPC applications. To achieve good performance, users often employ an iterative multistage tuning process to find an optimal I/O stack configuration. However, an I/O stack contains multiple layers, such as high-level I/O libraries, I/O middleware, and parallel file systems, and each layer has many parameters. These parameters and layers are entangled and influenced by each other. The tuning process is time-consuming and complex. In this work, we present TunIO, an AI- powered I/O tuning framework that implements several techniques to balance the tuning cost and performance gain, including tuning the high- impact parameters first. Furthermore, TunIO analyzes the application source code to extract its I/O kernel while retaining all statements necessary to perform I/O. It utilizes a smart selection of high-impact configuration parameters of the given tuning objective. Finally, it uses a novel Reinforcement Learning (RL)-driven early stopping mechanism to balance the cost and performance gain. Experimental results show that TunIO leads to a reduction of up to \u2248 73% in tuning time while achieving the same performance gain when compared to H5Tuner. It achieves a significant performance gain/cost of 208.4 MBps/min (I/O bandwidth for each minute spent in tuning) over existing approaches under our testing. Index Terms-AI-powered I/O tuning, storage stack tuning, autotun- ing, source code transformations, and I/O performance optimization","hasAbstract":true,"links":{"pdf":"https://grc.iit.edu/papers/2024/rajesh-2024-tunio-05a8.pdf"},"tags":["AI for I/O","I/O Stack Tuning"],"_projectIds":["hermes","chronolog","coeus"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["iowarp","coeus","deepio","chronolog","hermes"],"memberAuthors":["rajesh-neeraj","bateman-keith","byna-surendra","kougkas-anthony","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"OAC-2104013","projectId":"chronolog"},{"agency":"DOE","award":"DE-SC0023263","projectId":"coeus"}]}')}}]);